// Known-answer reproducibility (review C6, T5): runs each known-answer
// generator several times, in fresh processes, and fails on any byte
// difference between runs. CI runs it on Linux, macOS and Windows with
// Node 22 and 24 (.github/workflows/tiny-tracker.yml), so anyone can see the
// answers reproduce. Not a test file; run after `npm run build`:
//
//   node dist/test/repro-known-answers.js [--runs N] [--out DIR] [generator ...]
//
// It prints one line per run with the sha256 of the generated bytes and, with
// --out, keeps every run's bytes for upload. Exit 1 on any difference.
//
// Generators registered now:
//   surface   the 0.1 surface transcript of this tree (the recorder behind
//             test/surface.test.ts): ten configurations, 214 calls.
// To register another (the expected/ generator, at integration): add an
// entry to GENERATORS that returns the exact bytes it would write.

import { createHash } from "node:crypto";
import { mkdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { fileURLToPath } from "node:url";
import { canonicalize } from "../src/digest.js";
import { recordSurface } from "./support/surface.js";

const CLI = fileURLToPath(new URL("../src/cli.js", import.meta.url));

export interface Generator {
  name: string;
  /** The bytes this generator would write, for run number `run` (0-based). Must not depend on `run`. */
  generate(run: number): Promise<Buffer>;
}

export const GENERATORS: Generator[] = [
  {
    name: "surface",
    // OS-assigned ports (portBase 0); ports are masked in the transcript.
    generate: async () => Buffer.from(canonicalize(await recordSurface({ cli: CLI, portBase: 0 }) as never), "utf8"),
  },
];

export interface RunResult {
  generator: string;
  run: number;
  sha256: string;
  bytes: number;
}

/** Compares the runs of one generator; returns a message per run that differs from run 0. */
export function compareRuns(results: Array<{ run: number; sha256: string }>): string[] {
  if (results.length === 0) return ["no runs"];
  const first = results[0];
  return results.slice(1).filter((r) => r.sha256 !== first.sha256)
    .map((r) => `run ${r.run} differs from run ${first.run}: ${r.sha256} != ${first.sha256}`);
}

async function main(): Promise<void> {
  const argv = process.argv.slice(2);
  let runs = 3;
  let outDir: string | undefined;
  const names: string[] = [];
  for (let i = 0; i < argv.length; i++) {
    if (argv[i] === "--runs") runs = Number(argv[++i]);
    else if (argv[i] === "--out") outDir = argv[++i];
    else names.push(argv[i]);
  }
  if (!Number.isInteger(runs) || runs < 2) {
    process.stderr.write("--runs must be an integer of 2 or more\n");
    process.exit(2);
  }
  const unknown = names.filter((n) => !GENERATORS.some((g) => g.name === n));
  if (unknown.length) {
    process.stderr.write(`unknown generator(s): ${unknown.join(", ")}; known: ${GENERATORS.map((g) => g.name).join(", ")}\n`);
    process.exit(2);
  }
  let failed = false;
  for (const g of GENERATORS.filter((x) => names.length === 0 || names.includes(x.name))) {
    const results: RunResult[] = [];
    for (let run = 0; run < runs; run++) {
      const bytes = await g.generate(run);
      const sha256 = createHash("sha256").update(bytes).digest("hex");
      results.push({ generator: g.name, run, sha256, bytes: bytes.length });
      if (outDir) {
        mkdirSync(outDir, { recursive: true });
        writeFileSync(join(outDir, `${g.name}.run${run}.json`), bytes);
      }
      process.stdout.write(`${g.name} run ${run}: sha256 ${sha256} (${bytes.length} bytes)\n`);
    }
    const problems = compareRuns(results);
    for (const p of problems) process.stdout.write(`${g.name}: ${p}\n`);
    if (problems.length) failed = true;
  }
  process.stdout.write(`${failed ? "DIFFERENT" : "identical"}: node ${process.version}, ${process.platform}/${process.arch}\n`);
  process.exit(failed ? 1 : 0);
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  main().catch((e) => {
    process.stderr.write(`${(e as Error).stack ?? e}\n`);
    process.exit(1);
  });
}
